/** `hello` — The server's half of the handshake: the protocol range it speaks, and who this connection is. */
export interface Hello {
  /** Protocol major version. */
  v: 1;
  type: "hello";
  /** The event's own id. Stable across a retry of the same event. */
  id: string;
  /** When it happened, by Chips' clock. Stamped on the way in; a value the sender writes is replaced. */
  ts: string;
  /** A workspace identifier: `ws_` followed by a ULID. */
  workspace_id: string;
  /** The space, when the event belongs to one. */
  space_id?: string;
  /** The run, when the event belongs to one. */
  run_id?: string;
  /** Assigned by the server on append, monotonic per workspace. Absent on the way in. */
  seq?: number;
  /** Required on every client-originated write. Sending the same key twice is a no-op. */
  idempotency_key?: string;
  /** The participant an event is attributed to. */
  actor: {
    /** Whether a person, a harness, one of a harness's agents or Chips itself acted. */
    kind: "person" | "harness" | "agent" | "system";
    /** The participant id, or `system` for Chips. */
    id: string;
    /** For an agent: the harness it speaks through, whose budget and runs are the agent's (ADR 0087). Filled in by Chips. */
    harness_id?: string;
  };
  /** The negotiated range. A client picks a version inside it or is refused. */
  protocol: {
    /** Oldest major version the server accepts. */
    min: number;
    /** Newest major version the server speaks. */
    max: number;
  };
  /** Who the client is talking to. */
  server: {
    /** Usually `chipsd`. */
    name: string;
    /** The server's own version. */
    version: string;
  };
  /** The harness the token belongs to, and only that one. One connection speaks for all of the harness's agents (ADR 0087), which `agents` lists. A harness running inside another is a lane, not a duplicate. */
  harnesses: {
    /** A harness identifier: `hrn_` followed by a ULID. */
    harness_id: string;
    /** The harness's name in the workspace. */
    display_name: string;
    /** The person accountable for this harness. */
    owner_id: string;
    /** What the harness can do. */
    capabilities?: string[];
    /** True for a transient child minted for one lane, which inherits its lead's settings. */
    ephemeral?: boolean;
  }[];
  /** The harness this connection is: `harnesses[0]`, said once. Read this rather than the list. */
  harness?: {
    /** A harness identifier: `hrn_` followed by a ULID. */
    harness_id: string;
    /** The harness's name in the workspace. */
    display_name: string;
    /** The person accountable for this harness. */
    owner_id: string;
    /** What the harness can do. */
    capabilities?: string[];
    /** True for a transient child minted for one lane, which inherits its lead's settings. */
    ephemeral?: boolean;
  };
  /** The harness's agents, each with its rooms (ADR 0087). Everything the connection sends names one of them as `actor`; a harness's own id is read as its one agent in the room. Sent only to a harness that declares `agents`. */
  agents?: {
    /** A agent identifier: `agt_` followed by a ULID. */
    agent_id: string;
    /** The harness's own name for it. */
    key: string;
    /** What it is called, and so its @handle. */
    name: string;
    /** Whether it is the harness's Main agent. */
    lead: boolean;
    /** Archived when its thing was put away. */
    state: "active" | "archived";
    /** The rooms it is in. One at most, once one room per agent is the rule. */
    spaces: string[];
    /** The open room it is in (ADR 0087: one at a time), or `null` while it is free. What it says while free is held. */
    room?: string | null;
    /** How many of its words Chips is holding, said while it was in no room. */
    held?: number;
  }[];
  /** The level in force for this connection. */
  autonomy: 0 | 1 | 2 | 3;
  /** The rules that fill in the details. */
  policy?: {
    /** 0 observe, 1 ask first, 2 ask when it matters, 3 autonomous and report back. Presets that expand to rules. */
    autonomy: 0 | 1 | 2 | 3;
    /** Evaluated in order; the workspace cap always wins. */
    rules: {
      /** A glob over action kinds, for example `payment.*`. */
      match: string;
      /** Extra conditions on the action's flags, and for a command, how its parts start. */
      when?: {
        external?: boolean;
        irreversible?: boolean;
        money_usd_over?: number;
        risk?: "external" | "external_communication" | "irreversible" | "destructive" | "financial" | "credential" | "privacy" | "legal"[];
        /** For an action that carries a command (ADR 0239): the words a part of it starts with. A command goes ahead on such rules only when every part starts with one that allows it. */
        starts_with?: string[];
      };
      /** What to do when the rule matches. */
      decision: "allow" | "ask" | "deny";
      /** Who may answer, when the decision is `ask`. */
      approvers?: string[];
      /** Shown to the harness, and recorded in the audit log. */
      reason?: string;
      /** Turned off by a person (ADR 0195): kept in the list to turn back on, and skipped by the policy engine until then. */
      off?: boolean;
      /** Who made it by answering an ask with Always (ADR 0195). Filled in by Chips. */
      made_by?: string;
      /** When a person's answer made it (ADR 0195): Always, or This session. Filled in by Chips. A rule a person's answer made never allows an action that matters. */
      made_at?: string;
    }[];
  };
  /** The ceiling, and what has been spent. */
  budget?: {
    /** The ceiling for this harness. */
    limit_usd: number;
    /** Spent so far, estimated. */
    spent_usd: number;
  };
  /** The spaces this credential is a member of as it connects. A client that kept a cache drops what is not here: a membership it lost while away is the one event a replay can never bring it, because it is no longer in the space that event belongs to. */
  spaces?: string[];
  /** The workspace as it is called now. A device keeps the name it was told when it paired and takes this one when they differ, so a workspace renamed since is called by its new name without pairing again. Absent when the workspace has no name. */
  workspace?: {
    name: string;
  };
}

