/** `agent.attached` — An agent was put in a room: added, moved in, or brought back. Its harness is handed the room's last lines with it. */
export interface AgentAttached {
  /** Protocol major version. */
  v: 1;
  type: "agent.attached";
  /** The event's own id. Stable across a retry of the same event. */
  id: string;
  /** When it happened, by Chips' clock. Stamped on the way in; a value the sender writes is replaced. */
  ts: string;
  /** A workspace identifier: `ws_` followed by a ULID. */
  workspace_id: string;
  /** The space, when the event belongs to one. */
  space_id?: string;
  /** The run, when the event belongs to one. */
  run_id?: string;
  /** Assigned by the server on append, monotonic per workspace. Absent on the way in. */
  seq?: number;
  /** Required on every client-originated write. Sending the same key twice is a no-op. */
  idempotency_key?: string;
  /** The participant an event is attributed to. */
  actor: {
    /** Whether a person, a harness, one of a harness's agents or Chips itself acted. */
    kind: "person" | "harness" | "agent" | "system";
    /** The participant id, or `system` for Chips. */
    id: string;
    /** For an agent: the harness it speaks through, whose budget and runs are the agent's (ADR 0087). Filled in by Chips. */
    harness_id?: string;
  };
  /** The agent, in the room this event's `space_id` names. */
  agent_id: string;
  /** Who put it there: a person, its harness, or Chips (`system`). */
  by?: string;
  /** The room it left for this one, when moved. */
  moved_from?: string;
  /** The `agent.fork` this copy answers, when it is a fork's copy (ADR 0087, Fork). */
  fork_of?: string;
  /** The `agent.asked` this new agent answers, when a person asked for it (ADR 0108). */
  made_for?: string;
  /** The room's last lines before the agent joined, within the budget its harness gave in `hello` (ADR 0088, point 5). Added as it is sent to the harness; the log does not keep it. */
  catch_up?: {
    /** Oldest first, the newest that fit the budget. */
    lines: {
      /** Where in the log it happened. */
      seq: number;
      /** When. */
      at: string;
      /** `said`: a message, addressed to this harness or not. `joined` and `left`: somebody came into the room or went. `renamed`: somebody took a new name, or the room a new title. `archived` and `unarchived`: the room was put away or brought back. */
      kind: "said" | "joined" | "left" | "renamed" | "archived" | "unarchived";
      /** Who: the one who said it, came, went or took the new name; for the room's own lines, who retitled, archived or unarchived it. */
      from: {
        /** Their participant id, or `system`. */
        id: string;
        kind: "person" | "harness" | "agent" | "system";
        /** What they go by now. */
        name: string;
        /** Their standing in this room, when they are in it (SEC-15). */
        role?: "owner" | "member" | "guest";
        /** A person's standing in the workspace (SEC-15): the plain form says it after the name, so a guest's line reads as a guest's. Absent for an agent or a harness. */
        workspace_role?: "owner" | "admin" | "member" | "guest";
      };
      /** On `said`: the message. */
      message_id?: string;
      /** On `said`: the words as they read now, so an edited message reads edited; a deleted one is not a line. Cut with an ellipsis when the one line is longer than the whole budget. */
      text?: string;
      /** On `said`: what a voice note said, as the server heard it (ADR 0054). */
      transcript?: string;
      /** On `said`: the names of the files it carried. */
      files?: string[];
      /** On `said`: the agents it was for (ADR 0081, ADR 0087), so a harness can leave out a line one of its agents already took a turn on. Absent on a message from before Chips said so. */
      addressed_to?: string[];
      /** On `said`: the guard held it (ADR 0081), so it was for nobody. */
      held?: true;
      /** On `renamed`, for a participant: the name they took. */
      name?: string;
      /** On `renamed`, for a participant: the name they went by until then. */
      previous?: string;
      /** On `renamed`, for the room: its new title. */
      title?: string;
    }[];
    /** Where they start: after this `seq`. With a message, where the harness's own last turn in the room began, one that said something or passed with NO_REPLY (ADR 0105), else its joining; from the pull route, 0. */
    since_seq: number;
    /** Whether older lines after `since_seq` were left out to fit the budget. */
    truncated: boolean;
    /** A cursor: `GET /v1/spaces/:id/context?before=` this reads what came before these lines. */
    before: number;
    /** The room's files at their current version, newest first, the 20 newest (ADR 0099): with a message, as of it, its own files included; from the pull route, as of now. Each with a URL for this harness. Absent from a Chips before files, and when the room has none. */
    files?: {
      /** The file's name, which its versions share. */
      name: string;
      /** Which version this is: 1 for the first, counting each change of its bytes. */
      version: number;
      /** The attachment that is this version: what a post names in `replaces` when it changes it. */
      attachment_id: string;
      /** Lowercase hex digest of this version's bytes. */
      sha256: string;
      /** Size in bytes. */
      byte_size: number;
      /** Sniffed from the bytes on upload. */
      mime_type: string;
      /** Who posted this version, as a line's `from` says it. */
      by: {
        /** Their participant id. */
        id: string;
        kind: "person" | "harness" | "agent" | "system";
        /** What they go by now. */
        name: string;
      };
      /** When this version was posted. */
      at: string;
      /** The message that posted this version. */
      message_id?: string;
      /** Pixels, for a photo or a video. */
      width?: number;
      /** Pixels, for a photo or a video. */
      height?: number;
      /** Milliseconds, for a sound or a video. */
      duration_ms?: number;
      /** In one name's versions (`?name=`): the version this one was made from, as its post said (`message.post.replaces`). Absent where the post said nothing, or named no version of this file. */
      replaces?: string;
      /** For a harness: a signed URL for this version, bound to its token, as a message's attachments are. Absent for a person, who fetches it by id. */
      url?: string;
      /** When `url` stops working. */
      url_expires_at?: string;
    }[];
    /** What the room's job has spent, as of the message (for one Chips held, as of its hand-over, when a new job began), against what the room allows a job (ADR 0117). With a message only; the room note says it in words. Absent from a Chips before it. */
    spend?: {
      /** What the room allows a job, in US dollars: its own ceiling, or the default (3) when nobody has set one. */
      ceiling_usd: number;
      /** What the room's runs reported costing since the job began, in US dollars, every harness's together. */
      spent_usd: number;
      /** Where the job began: the `seq` of the last thing a person did in the room, or of the last brief handed into it, whichever is later; 0 when neither has happened. */
      since_seq: number;
      /** How many of the job's runs reported no cost, and so count nothing. */
      uncounted_runs: number;
    };
  };
}

