/** `approval.routed` — A pending approval handed to somebody else to answer (M5.5): a teammate, a role, or the lane's lead. Chips resolves `to` to ids, as it does on the request. */
export interface ApprovalRouted {
  /** Protocol major version. */
  v: 1;
  type: "approval.routed";
  /** The event's own id. Stable across a retry of the same event. */
  id: string;
  /** When it happened, by Chips' clock. Stamped on the way in; a value the sender writes is replaced. */
  ts: string;
  /** A workspace identifier: `ws_` followed by a ULID. */
  workspace_id: string;
  /** The space, when the event belongs to one. */
  space_id?: string;
  /** The run, when the event belongs to one. */
  run_id?: string;
  /** Assigned by the server on append, monotonic per workspace. Absent on the way in. */
  seq?: number;
  /** Required on every client-originated write. Sending the same key twice is a no-op. */
  idempotency_key?: string;
  /** The participant an event is attributed to. */
  actor: {
    /** Whether a person, a harness, one of a harness's agents or Chips itself acted. */
    kind: "person" | "harness" | "agent" | "system";
    /** The participant id, or `system` for Chips. */
    id: string;
    /** For an agent: the harness it speaks through, whose budget and runs are the agent's (ADR 0087). Filled in by Chips. */
    harness_id?: string;
  };
  /** A approval identifier: `apr_` followed by a ULID. */
  approval_id: string;
  /** Who should answer, as the router asks it: `owner`, `any`, `role:<name>`, `lead`, or a person id — the same words as `approvers` on the request. */
  to: string[];
  /** Who may answer now, as ids. Filled in by Chips from `to`; a value the sender writes is replaced. */
  approvers?: string[];
  /** What the ask is, written by Chips from the approval. Somebody handed an ask in a room they are not in never saw the request that raised it (ADR 0042), and this is what their card is drawn from; whoever is in the room has the request itself and ignores this. */
  ask?: {
    /** The harness that asked. */
    harness_id: string;
    /** The action as the harness proposed it. */
    action: {
      kind: string;
    };
    /** The risk classes it declared. */
    risk?: string[];
    /** When it expires, if it does. */
    expires_at?: string;
  };
  /** Why it was handed on, for the card and the audit. */
  reason?: string;
  /** Who handed it on. Filled in by Chips from the credential. */
  routed_by?: string;
  /** When. Filled in by Chips from its clock. */
  routed_at?: string;
}

