/** `exchange.limits_set` — An owner or an admin set when Chips tells the agents in any room to stop, when it holds their messages to each other, and whether agents going in circles are told to stop then (ADR 0187). Everyone's, in every room. */
export interface ExchangeLimitsSet {
  /** Protocol major version. */
  v: 1;
  type: "exchange.limits_set";
  /** The event's own id. Stable across a retry of the same event. */
  id: string;
  /** When it happened, by Chips' clock. Stamped on the way in; a value the sender writes is replaced. */
  ts: string;
  /** A workspace identifier: `ws_` followed by a ULID. */
  workspace_id: string;
  /** The space, when the event belongs to one. */
  space_id?: string;
  /** The run, when the event belongs to one. */
  run_id?: string;
  /** Assigned by the server on append, monotonic per workspace. Absent on the way in. */
  seq?: number;
  /** Required on every client-originated write. Sending the same key twice is a no-op. */
  idempotency_key?: string;
  /** The participant an event is attributed to. */
  actor: {
    /** Whether a person, a harness, one of a harness's agents or Chips itself acted. */
    kind: "person" | "harness" | "agent" | "system";
    /** The participant id, or `system` for Chips. */
    id: string;
    /** For an agent: the harness it speaks through, whose budget and runs are the agent's (ADR 0087). Filled in by Chips. */
    harness_id?: string;
  };
  /** After how many messages between agents, with nobody acting, Chips tells them to stop and tells the room's people. `null`: never, by count. Smaller than `hold` when both are set. */
  stop: number | null;
  /** After how many Chips holds their messages to each other until a person acts. `null`: never, by count; a pause still holds them. */
  hold: number | null;
  /** Whether agents going in circles (the same two or three taking turns and saying again what they said) are told to stop then, whatever the count. */
  circles: boolean;
}

