/** Any event a harness sends to Chips. */
export type HarnessToChipsEvent =
  | SessionStarted
  | SessionEnded
  | SessionRenamed
  | RunStarted
  | RunStatus
  | RunPlan
  | StepLog
  | MessagePost
  | MessageHeard
  | ApprovalRequest
  | QuestionAsk
  | ArtifactCreate
  | Checkpoint
  | Handoff
  | Task
  | Usage
  | ContextUsage
  | ApprovalExecuted
  | RunCompleted
  | RunFailed;

/** Any event Chips sends to a harness. */
export type ChipsToHarnessEvent =
  | Hello
  | MessageNew
  | MessageOverheard
  | RunRequested
  | ApprovalResolved
  | QuestionAnswered
  | RunSteer
  | RunPause
  | RunResume
  | RunCancel
  | PolicyUpdated
  | BudgetWarning
  | LaneUpdated
  | Feedback
  | Receipt;

/** Any Agent Connect event. */
export type AnyEvent = HarnessToChipsEvent | ChipsToHarnessEvent;
